<?php $this->layout('default'); use Moves\Services\CmsAudit; use Moves\Services\CmsAuth; use Moves\Services\PlatformBilling; use Moves\Services\PlatformDirectory as D; use Moves\Support\CmsView as V;
$c = D::company($id); if ($c === null) { http_response_code(404); echo V::empty('Empresa não encontrada.'); return; }
$manage = CmsAuth::can($admin, 'companies.manage'); $subs = CmsAuth::can($admin, 'subscriptions.view') ? PlatformBilling::subscriptions(['organization_id' => $id], 1)['rows'] : []; ?>
<div class="cms-grid-2"><div><div class="cms-card"><h2><?= V::e($c['trade_name'] ?: $c['name']) ?></h2><dl class="cms-dl"><dt>Razão social</dt><dd><?= V::e($c['name']) ?></dd><dt>Situação</dt><dd><?= V::badge($c['status'], $c['status'] === 'active' ? 'Ativa' : 'Inativa') ?></dd><dt>Responsável</dt><dd><a href="/usuarios/<?= (int) $c['owner_user_id'] ?>"><?= V::e($c['owner_first_name'] . ' ' . $c['owner_last_name']) ?></a> · <?= V::e($c['owner_email']) ?></dd><dt>Cadastro</dt><dd><?= V::date($c['created_at']) ?></dd></dl></div>
<div class="cms-card"><h2>Membros e acesso aos chamados</h2><p><small>O responsável sempre vê os chamados da empresa. Os demais membros só veem com autorização.</small></p><div class="cms-table-wrap"><table><thead><tr><th>Nome</th><th>Papel</th><th>Chamados</th></tr></thead><tbody><?php foreach (D::companyMembers($id) as $m): $owner = (int) $m['id'] === (int) $c['owner_user_id']; ?><tr><td><?= V::e($m['first_name'] . ' ' . $m['last_name']) ?><br><small><?= V::e($m['email']) ?></small></td><td><?= V::e($m['role_name']) ?></td><td><?php if ($owner): ?>Responsável<?php elseif ($manage): ?><?= $m['support_access'] ? V::actionButton('company-support-access', 'Remover', ['id' => $id, 'user_id' => $m['id'], 'grant' => 0]) : V::actionButton('company-support-access', 'Autorizar', ['id' => $id, 'user_id' => $m['id'], 'grant' => 1]) ?><?php else: ?><?= $m['support_access'] ? 'Autorizado' : 'Sem acesso' ?><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="cms-card"><h2>Plano e assinatura</h2><?php if ($subs === []): ?><?= V::empty('Sem assinatura registrada.') ?><?php else: foreach ($subs as $s): ?><p><a href="/assinaturas/<?= (int) $s['id'] ?>"><?= V::e($s['plan_name']) ?></a> · <?= V::badge($s['status'], V::SUB_STATUS[$s['status']] ?? $s['status']) ?></p><?php endforeach; endif; ?></div>
<?php if (CmsAuth::can($admin, 'audit.view')): ?><div class="cms-card"><h2>Histórico</h2><?php $logs = CmsAudit::listing(['type' => 'company', 'resource_id' => (string) $id], 1, 15)['rows']; if ($logs === []): ?><?= V::empty('Sem registros.') ?><?php else: foreach ($logs as $l): ?><p><small><?= V::date($l['created_at']) ?> · <?= V::e($l['event_type']) ?> · <?= V::e($l['actor_email'] ?? 'Sistema') ?></small></p><?php endforeach; endif; ?></div><?php endif; ?></div>
<aside><?php if ($manage): ?><form class="cms-card" method="post" action="/acao/company-status" data-confirm="Confirmar a alteração desta empresa?"><h2><?= $c['status'] === 'active' ? 'Inativar empresa' : 'Reativar empresa' ?></h2><?= V::csrf() ?><input type="hidden" name="id" value="<?= (int) $id ?>"><input type="hidden" name="active" value="<?= $c['status'] === 'active' ? 0 : 1 ?>"><?= V::field('Motivo', 'reason', '', ['type' => 'textarea', 'rows' => 2]) ?><button class="cms-btn"><?= $c['status'] === 'active' ? 'Inativar' : 'Reativar' ?></button></form><?php endif; ?></aside></div>
